import csv
import io

def parse_csv(raw_csv: str):
    csv.field_size_limit(2147483647)

    stream = io.StringIO(raw_csv, newline="")
    try:
        records = [list(row) for row in csv.reader(
            stream,
            delimiter=",",
            quotechar='"',
            doublequote=True,
            strict=False
        )]
    except csv.Error:
        records = []
        row = []
        field = []
        in_quotes = False
        i = 0
        length = len(raw_csv)

        while i < length:
            char = raw_csv[i]

            if in_quotes:
                if char == '"':
                    if i + 1 < length and raw_csv[i + 1] == '"':
                        field.append('"')
                        i += 2
                        continue
                    in_quotes = False
                else:
                    field.append(char)
            else:
                if char == '"' and not field:
                    in_quotes = True
                elif char == ",":
                    row.append("".join(field))
                    field = []
                elif char == "\r" or char == "\n":
                    row.append("".join(field))
                    field = []
                    records.append(row)
                    row = []
                    if char == "\r" and i + 1 < length and raw_csv[i + 1] == "\n":
                        i += 1
                else:
                    field.append(char)
            i += 1

        if field or row or (length > 0 and raw_csv[-1] == ","):
            row.append("".join(field))
            records.append(row)

    if records and records[0]:
        records[0][0] = records[0][0].lstrip("\ufeff")

    expected_width = 9
    header_row_count = 3
    best_index = None
    best_score = None

    for index in range(0, max(0, len(records) - header_row_count + 1)):
        header_block = records[index:index + header_row_count]
        if sum(len(row) for row in header_block) != expected_width:
            continue

        flattened = [value for row in header_block for value in row]
        score = 0

        for offset, row in enumerate(
            records[index + header_row_count:index + header_row_count + 25]
        ):
            if len(row) == expected_width:
                score += 20
            elif not row:
                score -= 1
            else:
                score -= min(abs(len(row) - expected_width), 5)

            if offset < 3 and len(row) == expected_width:
                score += 10

        score += sum(2 for value in flattened if value.strip())
        score -= index

        if best_score is None or score > best_score:
            best_score = score
            best_index = index

    if best_index is None:
        best_index = 0
        if len(records) > header_row_count:
            best_run_score = None
            for data_start in range(header_row_count, len(records)):
                score = 0
                for row in records[data_start:data_start + 25]:
                    if len(row) == expected_width:
                        score += 1
                if best_run_score is None or score > best_run_score:
                    best_run_score = score
                    best_index = data_start - header_row_count

    header_records = records[best_index:best_index + header_row_count]
    columns = [value for row in header_records for value in row]
    data_rows = records[best_index + header_row_count:]

    output_width = max(
        [expected_width, len(columns)] + [len(row) for row in data_rows]
    )

    used_names = set(columns)
    while len(columns) < output_width:
        number = len(columns) + 1
        name = "column_" + str(number)
        suffix = 2
        while name in used_names:
            name = "column_" + str(number) + "_" + str(suffix)
            suffix += 1
        columns.append(name)
        used_names.add(name)

    normalized_rows = []
    for row in data_rows:
        normalized = list(row)
        if len(normalized) < output_width:
            normalized.extend([""] * (output_width - len(normalized)))
        normalized_rows.append(normalized)

    return {"columns": columns, "rows": normalized_rows}
